const cloud = require('wx-server-sdk')
const fs = require('fs')
const path = require('path')

cloud.init({ env: cloud.DYNAMIC_CURRENT_ENV })

exports.main = async (event, context) => {
  const wxContext = cloud.getWXContext()
  const envId = wxContext.ENV || 'cloud1-3g3ayhyg41b2fe30';

  try {
    const prefix = 'southern-guangdong-scenery/';
    
    // Load image list from manifest file (generated by MCP tool)
    // This avoids dependency on storage listing APIs which are inconsistent across SDK versions
    const manifestPath = path.join(__dirname, 'images_manifest.json');
    let allFiles = [];
    
    if (fs.existsSync(manifestPath)) {
        allFiles = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
    } else {
        console.warn('Manifest file not found, using empty list');
    }
    
    // Filter for images (just in case manifest contains other files)
    const imageFiles = allFiles.filter(f => /\.(jpg|jpeg|png|gif|webp)$/i.test(f));
    
    // Random shuffle
    const shuffled = imageFiles.sort(() => 0.5 - Math.random());
    const selected = shuffled.slice(0, 5);
    
    if (selected.length === 0) {
        console.warn('No images found in manifest');
        return { images: [] };
    }

    // Correct FileID format for this environment:
    // cloud://<EnvID>.<BucketID>/<Path>
    // EnvID: cloud1-3g3ayhyg41b2fe30
    // BucketID: 636c-cloud1-3g3ayhyg41b2fe30-1405395592
    const bucketId = '636c-cloud1-3g3ayhyg41b2fe30-1405395592';
    
    const filesToUrl = selected.map(f => ({
      fileID: `cloud://${envId}.${bucketId}/${f}`,
      name: f.split('/').pop().replace(/\.[^/.]+$/, "")
    }));
    
    const urlResult = await cloud.getTempFileURL({
      fileList: filesToUrl.map(f => f.fileID)
    });
    
    return {
      images: urlResult.fileList.map((item, index) => ({
        url: item.tempFileURL,
        fileID: item.fileID,
        name: filesToUrl[index].name
      }))
    };
  } catch (err) {
    console.error('Error in getSceneryImages:', err);
    return { error: err.message, stack: err.stack };
  }
}
